/* Explicit stocks and production chains. All transfers conserve goods. */
const Economy=(()=>{
const raw=['timber','stone','iron'];const icons={money:'💰',food:'🌾',materials:'🧱',equipment:'⚔',timber:'🪵',stone:'🪨',iron:'⛏'};
function resources(cell){const b=cell.biome.i,forest=[5,6,7,8,9].includes(b),n=((cell.id*2654435761)>>>0)%100;return {timber:forest?1.4:.12,stone:cell.elevation>.55?.8:.18,iron:n<28&&cell.elevation>.25?.6:.04};}
function upgrade(s){s.release='0.3.0';s.tradeOffers=s.tradeOffers||[];s.tradeDeals=s.tradeDeals||[];s.shipments=s.shipments||[];s.nextTrade=s.nextTrade||1;s.countries.forEach(c=>{for(const k of raw)if(c.stock[k]===undefined)c.stock[k]={timber:80,stone:60,iron:40}[k];});return s;}
function manufacture(s,c,notes){const cells=s.cells.filter(x=>x.country===c.id&&x.land),workshops=cells.filter(x=>x.buildings.includes('workshop')).length,crafts=cells.filter(x=>x.buildings.includes('city')||x.buildings.includes('village')).length;const units=Math.max(0,Math.min(crafts+2*workshops,c.stock.timber/2,c.stock.stone));c.stock.timber-=units*2;c.stock.stone-=units;c.stock.materials+=units;const arms=Math.max(0,Math.min(workshops*(2+.2*c.tech.industry),c.stock.iron/2,c.stock.materials));c.stock.iron-=arms*2;c.stock.materials-=arms;c.stock.equipment+=arms;notes.push(`${c.name}: made ${units.toFixed(1)} building materials from timber + stone, and ${arms.toFixed(1)} equipment from iron + materials.`);}
function store(s,c,notes){const owned=s.cells.filter(x=>x.country===c.id&&x.land),cap=350+owned.filter(x=>x.buildings.includes('city')).length*150+owned.filter(x=>x.buildings.includes('granary')).length*300;let lost=0;for(const k of ['food','materials','equipment',...raw]){const spill=Math.max(0,c.stock[k]-cap);c.stock[k]-=spill;lost+=spill;}const spoil=c.stock.food*.01;c.stock.food-=spoil;if(lost>0)notes.push(`${c.name}: storage overflow lost ${lost.toFixed(1)} goods. Build a storehouse.`);return cap;}
function check(ok,message){if(!ok)throw Error(message);}
function propose(s,from,to,give,giveQty,take,takeQty){check(s.phase==='implement','Propose trades during Implement.');check(s.countries[from]&&s.countries[to]&&from!==to,'Choose another country.');check(Object.keys(icons).includes(give)&&Object.keys(icons).includes(take)&&give!==take,'Choose two different goods.');check(Number.isInteger(giveQty)&&giveQty>0&&giveQty<=500&&Number.isInteger(takeQty)&&takeQty>0&&takeQty<=500,'Trade amounts must be whole numbers from 1 to 500.');s.tradeOffers.push({id:s.nextTrade++,from,to,give,giveQty,take,takeQty});}
function accept(s,id,recipient,accepted){check(s.phase==='decide','Answer trades during Decide.');const i=s.tradeOffers.findIndex(o=>o.id===id),o=s.tradeOffers[i];check(o&&o.to===recipient,'Only the receiving country can answer.');if(accepted)s.tradeDeals.push({...o,remaining:3});s.tradeOffers.splice(i,1);}
function hub(s,country){return s.cells.find(c=>c.country===country&&c.buildings.includes('city'))||s.cells.find(c=>c.country===country&&c.buildings.includes('village'));}
function processTrade(s,notes,route,relation){for(const ship of s.shipments){if(ship.delivered)continue;if(relation(s,ship.from,ship.to)==='enemy'){notes.push(`Trade shipment ${ship.id} is held while its countries are at war.`);continue;}if(--ship.remaining<=0){s.countries[ship.to].stock[ship.good]+=ship.qty;ship.delivered=true;notes.push(`${s.countries[ship.to].name} received ${ship.qty} ${ship.good} from a trade shipment.`);}}s.shipments=s.shipments.filter(x=>!x.delivered);
for(const d of s.tradeDeals){if(d.remaining<=0)continue;d.remaining--;const a=s.countries[d.from],b=s.countries[d.to],from=hub(s,d.from),to=hub(s,d.to);if(relation(s,d.from,d.to)==='enemy'||!from||!to){notes.push(`Trade ${d.id} skipped: war or no settlement hub.`);continue;}const p=route(s,from.id,to.id,d.from);if(p===null){notes.push(`Trade ${d.id} skipped: no land route. Sea trade is not yet available.`);continue;}if(a.stock[d.give]<d.giveQty||b.stock[d.take]<d.takeQty){notes.push(`Trade ${d.id} skipped: one country lacks its promised goods. Neither side paid.`);continue;}a.stock[d.give]-=d.giveQty;b.stock[d.take]-=d.takeQty;const turns=Math.max(1,Math.ceil(p.length/4));s.shipments.push({id:s.nextTrade++,from:d.from,to:d.to,good:d.give,qty:d.giveQty,remaining:turns},{id:s.nextTrade++,from:d.to,to:d.from,good:d.take,qty:d.takeQty,remaining:turns});notes.push(`Trade ${d.id} dispatched: ${d.giveQty} ${d.give} ↔ ${d.takeQty} ${d.take}; arrival in ${turns} turns.`);}s.tradeDeals=s.tradeDeals.filter(d=>d.remaining>0);}
function validate(s){for(const c of s.countries)check(raw.every(k=>Number.isFinite(c.stock[k])&&c.stock[k]>=0),'Invalid raw-resource stocks.');check(Array.isArray(s.tradeOffers)&&Array.isArray(s.tradeDeals)&&Array.isArray(s.shipments),'Invalid trade data.');for(const d of [...s.tradeOffers,...s.tradeDeals])check(Number.isInteger(d.id)&&s.countries[d.from]&&s.countries[d.to]&&d.from!==d.to&&Object.keys(icons).includes(d.give)&&Object.keys(icons).includes(d.take)&&Number.isInteger(d.giveQty)&&d.giveQty>0&&Number.isInteger(d.takeQty)&&d.takeQty>0,'Invalid trade offer.');for(const d of s.shipments)check(Number.isInteger(d.id)&&s.countries[d.from]&&s.countries[d.to]&&Object.keys(icons).includes(d.good)&&Number.isFinite(d.qty)&&d.qty>0&&Number.isInteger(d.remaining)&&d.remaining>0,'Invalid shipment.');}
return {icons,resources,upgrade,manufacture,store,propose,accept,processTrade,validate};})();
